// Make the generated Android app resizable for windowed / freeform / desktop mode.
//
// android/ is gitignored and regenerated by `cap add android`, so the manifest
// cannot be edited in the tree; CI runs this after `cap add` instead. It only
// adds what a resizable window needs (resizeableActivity, the resize-related
// configChanges the activity does not already handle, a default window size
// and a 360dp minimum). It never adds or removes an orientation lock: if one
// is present it prints a warning and leaves it alone. Pure Node, no extra deps.
//
// Usage: node scripts/patch-android-manifest.mjs [path/to/AndroidManifest.xml]

import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';

const REQUIRED_CONFIG_CHANGES = [
  'orientation', 'screenSize', 'smallestScreenSize', 'screenLayout', 'density',
];

const LAYOUT =
  '<layout android:defaultWidth="640dp" android:defaultHeight="480dp" ' +
  'android:minWidth="360dp" android:minHeight="360dp" />';

/** Return { xml, notes } with the main activity patched; throws if it is not found. */
export function patchManifest(xml) {
  const notes = [];
  // The MAIN intent-filter is a child, so locate the activity that contains it.
  const blocks = [...xml.matchAll(/<activity\b[\s\S]*?<\/activity>/g)];
  const block = blocks.find((b) => /android\.intent\.action\.MAIN/.test(b[0]));
  if (!block) throw new Error('main activity (android.intent.action.MAIN) not found');

  const openTag = block[0].match(/^<activity\b[^>]*>/)[0];
  let tag = openTag;

  // resizeableActivity
  if (/android:resizeableActivity=/.test(tag)) {
    tag = tag.replace(/android:resizeableActivity="[^"]*"/, 'android:resizeableActivity="true"');
  } else {
    tag = tag.replace(/^<activity\b/, '<activity android:resizeableActivity="true"');
  }

  // configChanges: union with what is already declared
  const cc = tag.match(/android:configChanges="([^"]*)"/);
  const have = cc ? cc[1].split('|').map((s) => s.trim()).filter(Boolean) : [];
  const merged = [...have, ...REQUIRED_CONFIG_CHANGES.filter((x) => !have.includes(x))];
  const ccAttr = `android:configChanges="${merged.join('|')}"`;
  tag = cc ? tag.replace(cc[0], ccAttr) : tag.replace(/^<activity\b/, `<activity ${ccAttr}`);

  if (/android:screenOrientation=/.test(tag)) {
    notes.push('WARNING: main activity declares android:screenOrientation; left unchanged');
  }

  let body = block[0].replace(openTag, tag);
  if (!/<layout\b/.test(body)) {
    body = body.replace(/<\/activity>$/, `    ${LAYOUT}\n        </activity>`);
  }
  notes.push(`activity tag: ${tag}`);
  return { xml: xml.replace(block[0], body), notes };
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const path = process.argv[2] || 'android/app/src/main/AndroidManifest.xml';
  const { xml, notes } = patchManifest(await readFile(path, 'utf8'));
  await writeFile(path, xml);
  for (const n of notes) console.log(n);
  console.log(`patched ${path}`);
}
